constraint.cypher:
// Compare the BOUNDED CONTEXT segment, which for this layout is the
// one after the package root: com.wolper.aip.<context>.<layer>...
//
// The first version of this rule used
//   split(t.fqn, '.repository.')[0] <> split(p.fqn, '.repository.')[0]
// which is wrong: split() on a string that does NOT contain the
// separator returns the whole string, so an accessor was always
// compared against a value it could never equal. It reported every
// service reaching its OWN repository as a cross-context violation —
// four false positives on first run, and it would have reported them
// forever without anyone doubting a MAJOR constraint.
//
// $contextDepth is the 0-based index of the context segment.
// com.wolper.aip.jqa.service.JqaService -> index 3 = "jqa".
// Change it for your own package root before trusting this rule.
MATCH (t:Type)-[:DEPENDS_ON]->(p:Persistence)
WHERE NOT t:Persistence
  AND t.fqn =~ '.*\\.(service|api)\\..*'
WITH t, p,
     split(t.fqn, '.') AS accessorParts,
     split(p.fqn, '.') AS repoParts
WHERE size(accessorParts) > 3 AND size(repoParts) > 3
  AND accessorParts[3] <> repoParts[3]
RETURN t.fqn AS accessor, p.fqn AS foreignRepository
